// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerReminder, fillCollectionName, advanceToOptionalFieldsStep, enableSortOptionalField } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});


test('testUi', async ({ page }) => {
    test.setTimeout(944000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);

    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    await signIn(page, getValue(playwrightRequest0, "email"), getValue(playwrightRequest0, "password"));

    await dismissProjectOwnerReminder(page);
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await page.goto(`${baseUrl}/admin/logout`);

    const playwrightRequest1: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    const response1 = await signIn(page, getValue(playwrightRequest1, "email"), getValue(playwrightRequest1, "password"));
    expect(response1.status()).toBe(200);

    // Each sign-in re-raises the project-owner dialog; its overlay blocks the wizard
    // drawer, and it can only be dismissed from a page with no drawer open.
    await page.goto(`${baseUrl}/admin/content`);
    await dismissProjectOwnerReminder(page);
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await fillCollectionName(page, "wizard_draft_probe");
    await advanceToOptionalFieldsStep(page);
    await enableSortOptionalField(page);

    // Reload the wizard route so onMounted restores the autosaved draft.
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await expect(page.getByRole("textbox", { name: "A unique table name..." })).toHaveValue("wizard_draft_probe");
    await advanceToOptionalFieldsStep(page);
    await expect(page.getByRole("button", { name: "Finish Setup" })).toBeVisible();
    // DR-UC02-P1: the restored draft must keep the Sort optional field enabled.
    // A checked optional-field checkbox exposes the accessible name "check_box";
    // an unchecked one exposes "check_box_outline_blank".
    await expect(page.getByRole("checkbox", { name: "check_box", exact: true })).toBeVisible();
});
